package com.example.data.local

object DuaTranslationLocalization {

    fun getLocalizedTranslation(
        duaId: Int,
        language: String,
        defaultTranslation: String,
        hausa: String = "",
        yoruba: String = "",
        igbo: String = ""
    ): String {
        return when (language) {
            "Hausa" -> if (hausa.isNotBlank()) hausa else getHausaTranslation(duaId) ?: defaultTranslation
            "Yoruba" -> if (yoruba.isNotBlank()) yoruba else getYorubaTranslation(duaId) ?: defaultTranslation
            "Igbo" -> if (igbo.isNotBlank()) igbo else getIgboTranslation(duaId) ?: defaultTranslation
            "Arabic" -> getArabicExplanation(duaId) ?: defaultTranslation
            "French" -> getFrenchTranslation(duaId) ?: defaultTranslation
            "Spanish" -> getSpanishTranslation(duaId) ?: defaultTranslation
            "Urdu" -> getUrduTranslation(duaId) ?: defaultTranslation
            "Chinese" -> getChineseTranslation(duaId) ?: defaultTranslation
            else -> defaultTranslation
        }
    }

    private fun getArabicExplanation(id: Int): String? = when (id) {
        1 -> "فَاذْكُرُونِي بِالطَّاعَةِ أَذْكُرْكُم بِالمَغْفِرَةِ وَالثَّوَابِ، وَاشْكُرُوا لِي نِعَمِي وَلَا تَكْفُرُوهَا، وَأَكْثِرُوا مِنْ ذِكْرِ اللَّهِ تَعَالَى بِالتَّسْبِيحِ وَالتَّحْمِيدِ وَالتَّهْلِيلِ."
        2 -> "اللهم أنت ربي وخالقي لا معبود بحق سواك، أنا عبدك الخاضع لك، معترف بعهدك ووعدك بالجنة، أعوذ بك من شر ذنوبي، وأعترف بإنعامك عليّ وبذنبي، فاغفر لي فإنه لا يغفر الذنوب إلا أنت."
        3 -> "أتحصن باسم الله العظيم الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع لأقوالنا العليم بأحوالنا."
        4 -> "رضيت بالله رباً ومدبراً ومعبوداً، وبالإسلام ديناً ومنهاجاً، وبمحمد ﷺ نبياً ورسولاً صادقاً."
        5 -> "باسمك اللهم أموت (أنام) وباسمك أحيا (أستيقظ)، مفوضاً أمري كله إليك."
        6 -> "الحمد لله الذي رد عليّ روحي بعد النوم، وعافى جسدي من الأسقام، وأذن لي بذكره وشكره."
        7 -> "أعوذ بالله العظيم وبوجهه الكريم وسلطانه القديم من الشيطان الرجيم، اللهم افتح لي أبواب رحمتك."
