        79 -> "اے اللہ! میں تیرا بندہ، تیرے بندے کا بیٹا اور تیری بندی کا بیٹا ہوں، میری پیشانی تیرے ہاتھ میں ہے، مجھ پر تیرا حکم نافذ ہے، میرے بارے میں تیرا فیصلہ سراسر عدل پر مبنی ہے۔ میں تجھ سے تیرے ہر اس نام کے واسطے سے سوال کرتا ہوں کہ قرآن کو میرے دل کی بہار، میرے سینے کا نور اور میرے غم و فکر کو دور کرنے والا بنا دے۔"
        80 -> "اے اللہ! تو ہی اول ہے تجھ سے پہلے کچھ نہ تھا، تو ہی آخر ہے تیرے بعد کچھ نہ ہوگا، تو ہی ظاہر ہے تجھ سے اوپر کچھ نہیں، اور تو ہی باطن ہے تجھ سے قریب تر کچھ نہیں۔ ہمارا قرض ادا فرما اور ہمیں فقر و فاقہ سے بے نیاز کر دے۔"
        81 -> "اے اللہ! ہمارے تمام معاملات کا انجام بہترین فرما اور ہمیں دنیا کی رسوائی اور آخرت کے عذاب سے محفوظ فرما۔"
        82 -> "اے اللہ! میں تجھ سے دین پر ثابت قدمی اور نیکی پر پختہ ارادے کا سوال کرتا ہوں، اور تجھ سے قلب سلیم اور سچی زبان کا طلب گار ہوں۔"
        83 -> "اے اللہ! میں تیری پناہ مانگتا ہوں ایسے علم سے جو نفع نہ دے، ایسے دل سے جو خوف خدا سے نہ کانپے، ایسے نفس سے جو سیر نہ ہو اور ایسی دعا سے جو قبول نہ کی جائے۔"
        84 -> "آیت الکرسی: اللہ کے سوا کوئی معبود نہیں، وہ زندہ اور سب کا تھامنے والا ہے۔ نہ اسے اونگھ آتی ہے نہ نیند۔ آسمانوں اور زمین کا سب کچھ اسی کی ملکیت ہے۔"
        85 -> "صبح و شام سورۃ الاخلاص، سورۃ الفلق اور سورۃ الناس تین تین بار پڑھنا ہر شر سے مکمل حفاظت کا ذریعہ ہے۔"
        86 -> "ہم نے صبح کی اور تمام بادشاہی اللہ ہی کے لیے ہو گئی اور تمام حمد اللہ کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں۔ اے میرے رب! میں تجھ سے اس دن کی بھلائی اور اس کے بعد کی بھلائی مانگتا ہوں اور آگ و قبر کے عذاب سے تیری پناہ چاہتا ہوں۔"
        87 -> "ہم نے شام کی اور تمام بادشاہی اللہ ہی کے لیے ہو گئی اور تمام حمد اللہ کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں۔ اے میرے رب! میں تجھ سے اس رات کی بھلائی اور اس کے بعد کی بھلائی مانگتا ہوں۔"
        88 -> "اے اللہ! تیری ہی توفیق سے ہم نے صبح کی اور تیرے ہی حکم سے ہم نے شام کی، تیرے ہی حکم سے ہم جیتے ہیں اور تیرے ہی حکم سے ہم مرتے ہیں اور تیری ہی طرف دوبارہ جی اٹھنا ہے۔"
        89 -> "اے اللہ! تیری ہی توفیق سے ہم نے شام کی اور تیرے ہی حکم سے ہم نے صبح کی، تیرے ہی حکم سے ہم جیتے ہیں اور تیرے ہی حکم سے ہم مرتے ہیں اور تیری ہی طرف لوٹ کر جانا ہے۔"
        90 -> "میں اللہ کے مکمل کلمات کے ذریعے اس کی پیدا کردہ تمام چیزوں کے شر سے پناہ مانگتا ہوں (شام کے وقت تین بار)۔"
        91 -> "مجھے اللہ ہی کافی ہے اس کے سوا کوئی معبود نہیں، اسی پر میں نے بھروسا کیا اور وہی عرش عظیم کا رب ہے (صبح و شام سات بار)۔"
        92 -> "اے اللہ! میرے بدن کو عافیت دے، میرے کانوں کو عافیت دے، میری آنکھوں کو عافیت دے، تیرے سوا کوئی معبود نہیں۔ اے اللہ! میں کفر اور فقر سے تیری پناہ مانگتا ہوں (تین بار)۔"
        93 -> "سبحان اللہ وبحمدہ سو (100) بار صبح و شام پڑھنا گناہوں کی بخشش اور بلند درجات کا ذریعہ ہے۔"
        94 -> "اے ہمیشہ زندہ رہنے والے، اے کائنات کو سنبھالنے والے، تیری رحمت کے وسیلے سے فریاد کرتا ہوں، میرے تمام حالات سنوار دے اور پلک جھپکنے کے برابر بھی مجھے میرے نفس کے حوالے نہ فرما۔"
        95 -> "پاک ہے اللہ اپنی حمد کے ساتھ، اپنی مخلوق کی تعداد کے برابر، اپنی ذات کی رضا کے برابر، اپنے عرش کے وزن اور اپنے کلمات کی سیاہی کے برابر (صبح تین بار)۔"
        else -> null
    }

    private fun getChineseTranslation(id: Int): String? = when (id) {
        1 -> "故你们当记念我，我就记念你们；你们当感谢我，不要辜负我。信道的人们啊！你们应当常常记念真主。先知（愿主赐福之）说：'记念主的人与不记念主的人，其例犹如活人与死人。'"
        2 -> "主啊！你是我的养主，除你之外绝无应受崇拜者。你创造了我，我是你的仆人。我尽我所能坚守对你的誓约与承诺。我求你庇护我免遭我所犯罪恶的伤害。我承认你对我施予的一切恩典，我也坦白我的罪过。求你饶恕我吧，因为除你之外绝无人能饶恕一切罪过。"
        3 -> "奉安拉的尊名，借其尊名，天地间任何事物皆不能造成伤害，他是全聪的，全知的。"
        4 -> "我喜悦安拉为我的主宰，伊斯兰为我的宗教，穆罕默德（愿主赐福之）为我的先知。"
        5 -> "主啊！奉你的尊名我睡眠（死亡），奉你的尊名我醒来（复活）。"
        6 -> "一切赞颂全归安拉，他使我的身体恢复健康，把我的灵魂还给我，并准许我记念赞颂他。"
        7 -> "我求伟大的安拉、他尊贵的容颜与他永恒的权威庇护，免受被驱逐的恶魔侵扰。主啊！求你为我开启你的慈悯之门。"
        8 -> "主啊！我祈求你宏大的恩典与赏赐。"
        10 -> "奉安拉之名（Bismillah）。"
        11 -> "奉安拉之名于始末。"
        12 -> "一切赞颂全归安拉，他赐予我这些食物充饥，这不是依靠我自身的力量或能力。"
        13 -> "主啊！求你降福于你所赐予他们的给养，饶恕他们并慈悯他们。"
        14 -> "奉安拉之名。主啊！求你使恶魔远离我们，也使恶魔远离你将赐予我们的后代。"
        15 -> "赞美真主，他为我们制服了这乘骑，否则我们自己绝无能力驾驭它。我们最终必定归于我们的主。"
        16 -> "主啊！我求你庇护我免遭忧虑与悲伤、软弱与懒惰、吝啬与怯懦、沉重的债务以及受制于人。"
        17 -> "除安拉外绝无应受崇拜者，他是至伟至慈的。除安拉外绝无应受崇拜者，他是伟大宝座之主。除安拉外绝无应受崇拜者，他是诸天、大地与尊贵宝座的主宰。"
        18 -> "我向安拉祈求饶恕（三遍）。主啊！你是和平与赐安宁者，安宁全来自于你，拥有尊严与慷慨的主啊，你多福多寿。"
        19 -> "赞美安拉超绝（33遍），赞颂全归安拉（33遍），安拉至大（33遍）。万物非主，唯有真主，独一无二，统辖权与赞颂全归于他，他是全能于万事的。"
        20 -> "一切赞颂全归安拉。（回应）：愿安拉慈悯你。（答复）：愿安拉指引你并改善你的境遇。"
        21 -> "奉安拉之名。主啊！我求你庇护我免遭一切男女恶魔的污秽侵害。"
        22 -> "主啊！求你饶恕（Ghufranaka）。"
        23 -> "奉安拉之名（小净开始时）。"
        24 -> "我作证万物非主唯有真主，独一无二；我作证穆罕默德是他的仆人与使者。主啊！求你使我成为常悔罪之人与常自洁之人。"
        25 -> "我求安拉庇护免遭被驱逐的恶魔伤害。"
        27 -> "主啊！求你饶恕他、慈悯他、宽恕他，尊崇他的居所并拓宽他的坟墓。"
        28 -> "主啊！我凭你的全知向你祈求明断，凭你的全能向你祈求力量，并祈求你浩大的恩惠。"
        29 -> "我们确是属于安拉的，我们必定要归于他。主啊！求你在我所遭遇的灾难中赏赐我，并补偿我更好的。"
        30 -> "我向安拉祈求饶恕，并向他真诚悔罪。"
        31 -> "主啊！求你以你合法的给养使我知足而远离非法，以你的恩典使我只依赖你而无求于他人。"
        32 -> "主啊！求你降下有益的甘霖。"
        33 -> "我们蒙受了安拉的恩典与慈悯而得降甘霖。"
        34 -> "赞美真主，雷霆因赞颂他而赞念他，众天使因畏惧他而赞美他。"
        35 -> "主啊！我祈求这风中的祥善，求你庇护我免受其灾害。"
        36 -> "万物非主唯有真主，独一无二，国权与赞颂全归于他，他能使死者生、使生者死，他是永生不灭的主，一切祥善全在他手中，他全能于万事。"
        37 -> "我以安拉完美的言辞为你们祈求庇护，免遭一切恶魔、毒虫与邪恶嫉妒之眼的伤害。"
        38 -> "主啊！我求你庇护我免在明知的情况下以物配你，并求你饶恕我所不知的过错。"
        39 -> "此居所中的归信者与穆斯林啊，愿和平降临你们！真主意欲，我们随后也将加入你们。我们祈求真主赐予我们与你们平安。"
        40 -> "主啊！求你赐福给穆罕默德和他的家属，犹如你赐福给易卜拉欣和他的家属一样，你确是受赞颂的、光荣的主。"
        41 -> "一切赞颂全归安拉，他在使我们睡眠（死亡）后复苏我们，最终我们将复活归于他。"
        42 -> "一切赞颂全归安拉，他赐予我这件衣服穿戴，并非出于我自身的能力或谋略。"
        43 -> "主啊！一切赞颂全归于你，是你赐我这件衣物。我求你赐予它本身的好处及其用途之善，求你庇护我免受其害。"
        44 -> "愿你穿戴崭新，生活受人赞颂，并作为烈士归真。"
        45 -> "奉安拉之名（脱去衣服时遮蔽幽玄）。"
        46 -> "主啊！求你在我的心中赐予光明，在我的舌上赐予光明，在我的听觉与视觉中赐予光明，在我的上方与下方赐予光明。"
        47 -> "主啊！这完美号召与建立拜功的主，求你赐予穆罕默德最尊贵的品级，并使他登上你所许诺的赞美之位。"
        48 -> "穆斯林早晨探望生病的教胞，七万位天使为他祈祷至傍晚；傍晚探望则祈祷至清晨。"
        49 -> "不要紧，若真主意欲，这病痛定会成为消除罪过的纯洁。"
        50 -> "主啊！赞美你超绝，赞颂全归你，你的尊名多福，你的威严崇高，除你之外绝无应受崇拜者。"
        51 -> "赞美我伟大的主超绝（鞠躬时念3遍）。"
        52 -> "安拉已听见赞美他的人。我们的主啊，赞颂全归于你，充满吉祥与纯洁的无尽赞颂。"
        53 -> "赞美我至尊的主超绝（叩头时念3遍）。"
        54 -> "主啊！求你饶恕我；主啊！求你饶恕我。"
        55 -> "我的面容叩拜创造它、并以其大能开辟其听觉与视觉的主。安拉是至善的创造者，多福超绝！"
        56 -> "一切祝词、拜功与美德全归安拉。先知啊！愿安拉赐你平安、慈悯与吉庆。"
        57 -> "万物非主唯有真主，独一的主、万物的制伏者，诸天大地及其中间万物的主，万能者，常赦者。"
        58 -> "我求安拉完美的言辞庇护，免遭他的震怒与刑罚、仆人的邪恶以及恶魔的耳语侵害。"
        59 -> "我求安拉庇护免遭恶魔与恶梦之害（向左轻吐三口）。"
        60 -> "主啊！求你在你所引导的人中引导我，在你所赐康安的人中赐我安宁，庇护我免遭你所判定的灾祸。"
        61 -> "赞美至圣之君王超绝（念3遍，第三遍拉长声音）。"
        62 -> "主啊！赞美你超绝并赞颂你，我作证万物非主唯有你，我向你求饶并向你悔罪。"
        63 -> "愿安拉的平安、慈悯与吉庆降临你们。"
        64 -> "我求安拉完美的言辞庇护，免遭他所造万物的伤害。"
        65 -> "奉安拉之名我为你祈祷诵念，消除伤害你的一切，免受一切恶魂与嫉妒之眼的伤害，愿安拉医治你。"
        66 -> "主啊！我们托你抵御他们，求你庇护我们免遭他们的邪恶伤害。"
        67 -> "主啊！七层天之主与伟大宝座之主，求你成为我的庇护者，保护我免遭某人及其同伙的侵害。"
        68 -> "降示经典的主、清算迅速的主啊，求你击溃联军并震碎他们。"
        69 -> "主啊！随你意愿，求你为我抵御他们的危害。"
        70 -> "我确信安拉和他的众使者。我求安拉庇护免遭被驱逐的恶魔侵害。"
        71 -> "我求安拉庇护免遭恶魔侵扰（并在左肩方向轻吐三口）。"
        72 -> "主啊！唯有你使之容易的事才是容易的，若你意欲，你能使困难化为容易。"
        73 -> "凡犯罪的仆人，只要认真做好小净，礼两拜并祈求真主饶恕，真主必饶恕他。"
        74 -> "求安拉庇护免遭恶魔侵扰，并诵读宣礼词（邦克）以驱逐恶魔。"
        75 -> "这是安拉的前定，他做他所意欲的一切。"
        76 -> "愿真主降福于赐予你的新生儿，愿你感谢赐予者，愿孩子健康成长并孝敬于你。"
        77 -> "主啊！求你饶恕我、慈悯我，使我归入至高同伴的行列。"
        78 -> "主啊！求你改善我的宗教，那是我的保障；求你改善我的今世，那是我的生活所在；求你改善我的后世，那是我最终的归宿；求你使生命成为我增添一切善行的机会，使死亡成为我脱离一切罪恶的安息。"
        79 -> "主啊！我是你的仆人，你仆人的儿子。求你以属于你的每一个尊名，使古兰经成为我心灵的春天、胸怀的光明、忧伤的消除者与焦虑的抚平者。"
        80 -> "主啊！你是最先的，在你之前无物；你是最后的，在你之后无物。求你为我们清偿债务，消除我们的贫困。"
        81 -> "主啊！求你使我们所有事情的结局皆得善终，求你庇护我们免遭今世的屈辱与后世的刑罚。"
        82 -> "主啊！我祈求在正道上坚定不移，在善功上坚决果断，祈求一颗纯洁的心灵与诚实的舌头。"
        83 -> "主啊！我求你庇护我免遭无益的知识、无敬畏的心灵、无节制的私欲与不被应答的祈求。"
        84 -> "库尔西经文：安拉！除他外绝无应受崇拜者，他是永生不灭的，维护万物的。瞌睡不能克服他，睡眠不能克服他。天地万物全归他所有。"
        85 -> "早晚各诵读忠诚章、曙光章与人类章3遍，足以抵御一切祸害与侵害。"
        86 -> "我们迎来了早晨，国权全归安拉，一切赞颂全归安拉。万物非主唯有真主，独一无二。主啊！我祈求这日的吉祥与以后的福祉，求你庇护我免受火狱与坟墓的刑罚。"
        87 -> "我们迎来了傍晚，国权全归安拉，一切赞颂全归安拉。万物非主唯有真主，独一无二。主啊！我祈求今夜的平安与以后的吉祥。"
        88 -> "主啊！依靠你我们进入清晨，依靠你我们进入傍晚，依靠你我们生活，依靠你我们死亡，我们最终将复活归于你。"
        89 -> "主啊！依靠你我们进入傍晚，依靠你我们进入清晨，依靠你我们生活，依靠你我们死亡，我们最终将归于你。"
